 11366   */
 11367  static int
 11368  xmlCheckCdataPush(const xmlChar *utf, int len, int complete) {
 11369      int ix;
 11370      unsigned char c;
 11371      int codepoint;
 11372
 11373      if ((utf == NULL) || (len <= 0))
 11374          return(0);
 11375
 11376      for (ix = 0; ix < len;) {      /* string is 0-terminated */
 11377          c = utf[ix];
 11378          if ((c & 0x80) == 0x00) {       /* 1-byte code, starts with 10 */
 11379              if (c >= 0x20)
 11380                  ix++;
 11381              else if ((c == 0xA) || (c == 0xD) || (c == 0x9))
 11382                  ix++;
 11383              else
 11384                  return(-ix);
 11385          } else if ((c & 0xe0) == 0xc0) {/* 2-byte code, starts with 110 */
 11386              if (ix + 2 > len) return(complete ? -ix : ix);
 11387              if ((utf[ix+1] & 0xc0 ) != 0x80)
 11388                  return(-ix);
 11389              codepoint = (utf[ix] & 0x1f) << 6;
 11390              codepoint |= utf[ix+1] & 0x3f;
 11391              if (!xmlIsCharQ(codepoint))
 11392                  return(-ix);
 11393              ix += 2;
 11394          } else if ((c & 0xf0) == 0xe0) {/* 3-byte code, starts with 1110 */
 11395              if (ix + 3 > len) return(complete ? -ix : ix);
 11396              if (((utf[ix+1] & 0xc0) != 0x80) ||
 11397                  ((utf[ix+2] & 0xc0) != 0x80))
 11398                      return(-ix);
 11399              codepoint = (utf[ix] & 0xf) << 12;
 11400              codepoint |= (utf[ix+1] & 0x3f) << 6;
 11401              codepoint |= utf[ix+2] & 0x3f;
 11402              if (!xmlIsCharQ(codepoint))
 11403                  return(-ix);
 11404              ix += 3;
 11405          } else if ((c & 0xf8) == 0xf0) {/* 4-byte code, starts with 11110 */
 11406              if (ix + 4 > len) return(complete ? -ix : ix);
 11407              if (((utf[ix+1] & 0xc0) != 0x80) ||
 11408                  ((utf[ix+2] & 0xc0) != 0x80) ||
 11409                  ((utf[ix+3] & 0xc0) != 0x80))
 11410                      return(-ix);
 11411              codepoint = (utf[ix] & 0x7) << 18;
 11412              codepoint |= (utf[ix+1] & 0x3f) << 12;
 11413              codepoint |= (utf[ix+2] & 0x3f) << 6;
 11414              codepoint |= utf[ix+3] & 0x3f;
 11415              if (!xmlIsCharQ(codepoint))
 11416                  return(-ix);
 11417              ix += 4;
 11418          } else                          /* unknown encoding */
 11419              return(-ix);
 11420        }
 11421        return(ix);
 11422  }
